<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');}$config=require __DIR__.'/config.php';function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$stores=$pdo->query("SELECT id,nombre FROM tiendas WHERE estado='activa' ORDER BY nombre")->fetchAll();$users=$pdo->query('SELECT u.id,u.nombre,u.email,u.rol,u.telefono,t.nombre AS tienda FROM usuarios u LEFT JOIN tiendas t ON t.id=u.tienda_id ORDER BY u.id DESC')->fetchAll();}catch(Throwable $e){http_response_code(500);exit('No se pudieron cargar los usuarios.');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuarios</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0}main{max-width:950px;margin:auto;padding:30px 20px}.card{background:#fff;padding:24px;border-radius:16px;margin:16px 0}label{display:block;margin:9px 0 4px}input,select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #ccc;border-radius:7px}button{margin-top:13px;padding:10px 16px;background:#886c42;color:#fff;border:0;border-radius:7px}a{color:#886c42}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px 7px;border-bottom:1px solid #eee}</style></head><body><main><p><a href="panel.php">← Panel</a></p><section class="card"><h1>Usuarios y permisos</h1><form method="post" action="usuario-guardar.php"><label>Nombre</label><input name="nombre" required maxlength="100"><label>Correo</label><input type="email" name="email" required maxlength="150"><label>Contraseña temporal</label><input type="password" name="password" required minlength="8"><label>Rol</label><select name="rol"><option value="admin_tienda">Administrador de tienda</option><option value="vendedor">Vendedor</option><option value="repartidor">Repartidor</option></select><label>Tienda</label><select name="tienda_id" required><?php foreach($stores as $s):?><option value="<?=$s['id']?>"><?=h($s['nombre'])?></option><?php endforeach;?></select><label>Teléfono</label><input name="telefono" maxlength="20"><button>Crear usuario</button></form></section><section class="card"><h2>Usuarios registrados</h2><table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Tienda</th><th>Teléfono</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=h($u['nombre'])?></td><td><?=h($u['email'])?></td><td><?=h($u['rol'])?></td><td><?=h($u['tienda']??'Global')?></td><td><?=h($u['telefono']??'')?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
